GPUImage::GPUImage(int width, int height, int gpu_device) {
    /*Start out Assuming Initialized Incorrectly*/
    initialized_correctly_ = false;

    /*CUDA Error Status*/
    cudaGetLastError(); // Resets Errors
    cudaError_t cudaStatus;

    /*Initialize Pinned Memory for Slightly Faster Transfer*/
    cudaHostAlloc(
        (void**)&bounding_box_, 4 * sizeof(int), cudaHostAllocDefault);
    bounding_box_[0] = 0;
    bounding_box_[1] = 0;
    bounding_box_[2] = width - 1;
    bounding_box_[3] = height - 1;

    /*Choose which GPU to run on, change this on a multi-GPU system.*/
    cudaSetDevice(gpu_device);

    /*Check for Errors*/
    cudaStatus = cudaGetLastError();
    if (cudaStatus != cudaSuccess) {
        image_on_gpu_ = false;
    } else {
        /*Initialize Private Host Variables*/
        width_ = width;
        height_ = height;
        device_ = gpu_device;
        dev_image_ = 0;

        /*Allocate GPU buffers for image, triangles.*/
        cudaMalloc(
            (void**)&dev_image_, width_ * height_ * sizeof(unsigned char));

        /*Check for Errors*/
        cudaStatus = cudaGetLastError();
        if (cudaStatus != cudaSuccess) {
            image_on_gpu_ = false;
            /*Free CUDA*/
            cudaFree(dev_image_);
        } else {
            image_on_gpu_ = true;
        }
    }
    /*Correctly Initialized*/
    initialized_correctly_ = true;
};

GPUImage::GPUImage(
    int width, int height, int gpu_device, unsigned char* host_image) {
    /*Start out Assuming Initialized Incorrectly*/
    initialized_correctly_ = false;

    /*CUDA Error Status*/
    cudaGetLastError(); // Resets Errors
    cudaError_t cudaStatus;

    /*Initialize Pinned Memory for Slightly Faster Transfer*/
    cudaHostAlloc(
        (void**)&bounding_box_, 4 * sizeof(int), cudaHostAllocDefault);
    bounding_box_[0] = 0;
    bounding_box_[1] = 0;
    bounding_box_[2] = width - 1;
    bounding_box_[3] = height - 1;

    /*Choose which GPU to run on, change this on a multi-GPU system.*/
    cudaSetDevice(gpu_device);

    /*Check for Errors*/
    cudaStatus = cudaGetLastError();
    if (cudaStatus != cudaSuccess) {
        cudaFreeHost(bounding_box_);
        initialized_correctly_ = false;
        image_on_gpu_ = false;
        return;
    }
    /*Initialize Private Host Variables*/
    width_ = width;
    height_ = height;
    device_ = gpu_device;
    dev_image_ = 0;

    /*Allocate GPU buffers for image, triangles.*/
    cudaMalloc((void**)&dev_image_, width_ * height_ * sizeof(unsigned char));

    /*Check for Errors*/
    cudaStatus = cudaGetLastError();

    if (cudaStatus != cudaSuccess || width_ * height_ == 0) {
        initialized_correctly_ = false;
        image_on_gpu_ = false;
        /*Free CUDA*/
        cudaFree(dev_image_);
        cudaFreeHost(bounding_box_);
        return;
    }
    /*Upload Image from Host to Device*/
    cudaMemcpy(
        dev_image_,
        host_image,
        width_ * height_ * sizeof(unsigned char),
        cudaMemcpyHostToDevice);

    /*Check for Errors*/
    cudaStatus = cudaGetLastError();

    if (cudaStatus != cudaSuccess) {
        initialized_correctly_ = false;
        image_on_gpu_ = false;
        /*Free CUDA*/
        cudaFree(dev_image_);
        cudaFreeHost(bounding_box_);
        return;
    }
    /*Correctly Initialized*/
    initialized_correctly_ = true;
    image_on_gpu_ = true;
    return;
};

